-- ===========================================================================
-- Seed 25 : quizzes for the C# course
--
-- One per level. Like the other courses without a runner there is no
-- scratchpad on these pages: the playground cannot run C#, and an HTML
-- scratchpad under a C# question would be worse than none.
-- starter_for_course() in the website returns null for this course.
--
-- Generated by scratchpad/gen/build_batch5.py, which also checks that every
-- single_choice has exactly one correct option and every multiple_choice has
-- at least two. A quiz that cannot be passed is not obvious from the SQL.
-- ===========================================================================

INSERT INTO assessment_quizzes
  (id, course_id, lesson_id, title, description, pass_percent, time_limit_seconds,
   max_attempts, shuffle_questions, shuffle_options, show_answers, status)
VALUES
  ('f0000001-0000-4000-8000-000000000028',
   'c0000001-0000-4000-8000-00000000000d', 'e0000001-0000-4000-8000-0000000000ad',
   'Level 1 Check: Types, Nullability and Collections',
   'Value types against references, what ! really does, and how LINQ behaves. Every one of these can be settled in a scratch console project.',
   60, 600, NULL, 0, 1, 1, 'published'),

  ('f0000001-0000-4000-8000-000000000029',
   'c0000001-0000-4000-8000-00000000000d', 'e0000001-0000-4000-8000-0000000000ae',
   'Level 2 Check: Records, Interfaces and Failure',
   'class against struct against record, generics and variance, and which failures to catch.',
   60, 720, NULL, 0, 1, 1, 'published'),

  ('f0000001-0000-4000-8000-00000000002a',
   'c0000001-0000-4000-8000-00000000000d', 'e0000001-0000-4000-8000-0000000000af',
   'Level 3 Check: async, LINQ and Patterns',
   'What await frees, deferred execution, data races, and matching on shape.',
   70, 720, NULL, 0, 1, 1, 'published'),

  ('f0000001-0000-4000-8000-00000000002b',
   'c0000001-0000-4000-8000-00000000000d', 'e0000001-0000-4000-8000-0000000000b0',
   'Expert Exam: C#',
   'Disposal, allocation, the JIT, and how an application is arranged.',
   70, 1500, 3, 1, 1, 1, 'published')
ON DUPLICATE KEY UPDATE
  title = VALUES(title), description = VALUES(description),
  pass_percent = VALUES(pass_percent), status = VALUES(status);

INSERT INTO assessment_questions
  (id, quiz_id, kind, prompt, explanation, points, `position`, correct_text)
VALUES
  -- Level 1 Check: Types, Nullability and Collections
  ('a1000001-0000-4000-8000-0000000002bd', 'f0000001-0000-4000-8000-000000000028', 'single_choice',
   'With nullable reference types enabled, what does `maybe!.Length` do?',
   'It tells the compiler to stop warning, and inserts nothing that checks anything at compile time. If the value is null at runtime the program throws a NullReferenceException. Every `!` is a place the program can crash - `??` or an `is not null` check is almost always shorter and safer.',
   2, 1, NULL),

  ('a1000001-0000-4000-8000-0000000002be', 'f0000001-0000-4000-8000-000000000028', 'single_choice',
   '`dictionary["missing"]` where the key is absent does what?',
   'It throws KeyNotFoundException. That is the opposite of Java''s map, which returns null, and it is why C# gives you TryGetValue and GetValueOrDefault - use those wherever a miss is possible.',
   2, 2, NULL),

  ('a1000001-0000-4000-8000-0000000002bf', 'f0000001-0000-4000-8000-000000000028', 'multiple_choice',
   'Which statements about LINQ are true? Select all that apply.',
   'Where and Select are deferred: they build a query and run when enumerated. They also capture the source rather than copying it, so a later change to the list shows up in the query. Enumerating twice runs the projection twice, which matters when it costs money or has a side effect - ToList() is where you pay once. LINQ does not modify the source collection.',
   3, 3, NULL),

  ('a1000001-0000-4000-8000-0000000002c0', 'f0000001-0000-4000-8000-000000000028', 'single_choice',
   'What is the difference between `const` and `readonly` on a field?',
   'A const is compile-time and is baked into every assembly that uses it - change it and dependants must be recompiled. A readonly field is set at runtime, in the constructor, so it can differ per instance and can hold any type. Prefer readonly for anything that might change or that is not a primitive.',
   2, 4, NULL),

  ('a1000001-0000-4000-8000-0000000002c1', 'f0000001-0000-4000-8000-000000000028', 'true_false',
   'A `switch` expression with no matching arm returns the default value for its type.',
   'False. It throws SwitchExpressionException. That is deliberate: a silent default hides the case you forgot, and a loud failure at the point of the missing arm is far easier to diagnose. It is also why `_ =>` should be a real decision rather than a reflex.',
   2, 5, NULL),

  -- Level 2 Check: Records, Interfaces and Failure
  ('a1000001-0000-4000-8000-0000000002c2', 'f0000001-0000-4000-8000-000000000029', 'single_choice',
   'When should you reach for a `record` rather than a `class`?',
   'When the object is its data: a coordinate, a money amount, a row read from a database, a message about to be serialised. A record generates value equality, ToString and `with` from its components. A class is right when the object has identity and behaviour beyond its fields, or when its state must change.',
   2, 1, NULL),

  ('a1000001-0000-4000-8000-0000000002c3', 'f0000001-0000-4000-8000-000000000029', 'multiple_choice',
   'Which statements about structs are true? Select all that apply.',
   'A struct is a value type: assignment copies it, and a copy of a mutable struct is a separate object - which is why a mutable struct is a classic source of confusion. Boxing one (assigning it to object or a non-generic interface) allocates. They are best kept small and immutable; `readonly struct` says so to the compiler.',
   3, 2, NULL),

  ('a1000001-0000-4000-8000-0000000002c4', 'f0000001-0000-4000-8000-000000000029', 'single_choice',
   'Why is `IEnumerable<out T>` covariant but `List<T>` not?',
   'You can only take things out of an IEnumerable, so an IEnumerable<string> is safely an IEnumerable<object>. A List<T> can be both read and written: if a List<string> were a List<object>, you could add an int to it and the string reader would break. `out` marks the read-only direction, `in` the write-only one.',
   3, 3, NULL),

  ('a1000001-0000-4000-8000-0000000002c5', 'f0000001-0000-4000-8000-000000000029', 'single_choice',
   'What does `throw;` inside a catch block do that `throw e;` does not?',
   'It preserves the original stack trace. `throw e;` resets the trace to that line, which discards the only record of where the failure actually came from. When you need to add context, wrap: `throw new XException("...", e)` keeps the original as InnerException.',
   3, 4, NULL),

  ('a1000001-0000-4000-8000-0000000002c6', 'f0000001-0000-4000-8000-000000000029', 'single_choice',
   'What is `catch (SomeException e) when (e.Code == 42)` good for?',
   'The filter runs BEFORE the stack unwinds. If it does not match, the exception carries on with its original context intact - which matters for debugging and for any outer handler. A filter is strictly better than catching, testing, and rethrowing.',
   3, 5, NULL),

  -- Level 3 Check: async, LINQ and Patterns
  ('a1000001-0000-4000-8000-0000000002c7', 'f0000001-0000-4000-8000-00000000002a', 'multiple_choice',
   'Which statements about async/await in C# are true? Select all that apply.',
   'await frees the thread rather than blocking it, which is the entire point. Starting tasks and then awaiting Task.WhenAll costs the slowest rather than the sum. `async void` cannot be awaited, so nothing observes its exceptions - it is only for event handlers. And .Result or .Wait() blocks, which deadlocks in any context with a synchronisation context.',
   3, 1, NULL),

  ('a1000001-0000-4000-8000-0000000002c8', 'f0000001-0000-4000-8000-00000000002a', 'single_choice',
   'What does a `CancellationToken` parameter oblige you to do?',
   'Pass it down to everything you call that accepts one, and let the OperationCanceledException it produces travel. Swallowing that exception turns a cancelled request into one that appears to have succeeded, which is worse than either outcome on its own.',
   3, 2, NULL),

  ('a1000001-0000-4000-8000-0000000002c9', 'f0000001-0000-4000-8000-00000000002a', 'single_choice',
   'Four threads each run `counter++` 100,000 times on a shared int. What do you get?',
   'Usually less than 400,000. `counter++` is read, add, write, and the threads interleave inside it - so increments are lost. Worse, without a memory barrier a thread may not see another''s writes at all. `lock`, `Interlocked.Increment`, or not sharing mutable state are the three fixes.',
   3, 3, NULL),

  ('a1000001-0000-4000-8000-0000000002ca', 'f0000001-0000-4000-8000-00000000002a', 'single_choice',
   'What does `if (value is string { Length: > 3 } s)` test?',
   'Three things at once: that the value is a string, that its Length is greater than three, and - if both hold - it binds it to `s`, typed and in scope only where the test passed. That is a type pattern, a property pattern and a declaration in one expression.',
   2, 4, NULL),

  ('a1000001-0000-4000-8000-0000000002cb', 'f0000001-0000-4000-8000-00000000002a', 'true_false',
   '`Parallel.ForEach` is a good way to speed up a loop that calls a web API for each item.',
   'False. Parallel.ForEach is for CPU-bound work: it occupies threads, and a thread blocked on a network call is a wasted one. For I/O, start the async operations and await Task.WhenAll - or use Parallel.ForEachAsync, which is designed for exactly this and takes a concurrency limit.',
   2, 5, NULL),

  -- Expert Exam: C#
  ('a1000001-0000-4000-8000-0000000002cc', 'f0000001-0000-4000-8000-00000000002b', 'multiple_choice',
   'Which of these cause a memory leak in .NET? Select all that apply.',
   'A leak in a collected runtime is a reference you forgot. An event subscription is the classic: the publisher''s delegate list holds the subscriber. A static collection that only grows, and a cache with no eviction, are the other two. A local variable going out of scope is the opposite - that is exactly what makes an object collectable.',
   3, 1, NULL),

  ('a1000001-0000-4000-8000-0000000002cd', 'f0000001-0000-4000-8000-00000000002b', 'single_choice',
   'What is `IDisposable` for, given that the GC frees memory?',
   'Everything the collector does not manage: file handles, sockets, database connections, OS handles of any kind. These are limited resources with their own lifetimes, and `using` releases them at a point you choose rather than whenever a collection happens to run.',
   3, 2, NULL),

  ('a1000001-0000-4000-8000-0000000002ce', 'f0000001-0000-4000-8000-00000000002b', 'single_choice',
   'Your benchmark loop is much faster on its fifth round than its first. Why?',
   'The JIT. .NET compiles IL to machine code on first execution, and tiered compilation then recompiles the hot methods with better optimisation. Early iterations measure the compiler, not the code. Warm up, use later rounds, and for anything you will act on use BenchmarkDotNet, which handles it properly.',
   3, 3, NULL),

  ('a1000001-0000-4000-8000-0000000002cf', 'f0000001-0000-4000-8000-00000000002b', 'single_choice',
   'Where should a repository interface live, in a layered application?',
   'With the domain that needs it. Then the database project references the domain rather than the other way round, and the rules can be tested with a four-line in-memory implementation. Putting it in the data layer inverts the arrow and drags the framework into the domain''s tests.',
   3, 4, NULL),

  ('a1000001-0000-4000-8000-0000000002d0', 'f0000001-0000-4000-8000-00000000002b', 'multiple_choice',
   'Which describe an application that stays easy to change? Select all that apply.',
   'Domain types that import no framework can be tested with a constructor call. Dependencies declared as interfaces and passed in keep the arrows pointing inward, and `internal` by default keeps the public surface small and deliberate. Naming a class after the pattern used describes the mechanism rather than the problem, and ages badly.',
   3, 5, NULL)
ON DUPLICATE KEY UPDATE
  prompt = VALUES(prompt), explanation = VALUES(explanation),
  points = VALUES(points), `position` = VALUES(`position`);

DELETE FROM assessment_question_options
 WHERE question_id IN (
   SELECT id FROM assessment_questions
    WHERE quiz_id IN ('f0000001-0000-4000-8000-000000000028',
                      'f0000001-0000-4000-8000-000000000029',
                      'f0000001-0000-4000-8000-00000000002a',
                      'f0000001-0000-4000-8000-00000000002b'));

INSERT INTO assessment_question_options (question_id, body, is_correct, `position`)
SELECT v.question_id, v.body, v.is_correct, v.pos
  FROM (
    SELECT 'a1000001-0000-4000-8000-0000000002bd' AS question_id, 'Silences the warning and throws at runtime if it really is null' AS body, 1 AS is_correct, 1 AS pos
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002bd', 'Converts the value to a non-nullable type safely', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002bd', 'Returns 0 when the value is null', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002bd', 'Is a compile error unless the compiler can prove it is not null', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002be', 'Throws KeyNotFoundException', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002be', 'Returns null', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002be', 'Returns the default value for the value type', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002be', 'Inserts the key with a default and returns it', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002bf', 'Where and Select do nothing until the query is enumerated', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002bf', 'Enumerating the same query twice runs the projection twice', 1, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002bf', 'The query captures the source, so later additions appear in it', 1, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002bf', 'OrderBy sorts the original list in place', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002c0', 'const is compile-time and inlined into callers; readonly is set at runtime', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002c0', 'They are the same, and const is the older spelling', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002c0', 'readonly is compile-time and const is runtime', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002c0', 'const works on any type; readonly only on primitives', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002c1', 'True', 0, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002c1', 'False', 1, 2

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002c2', 'When the object is its data and should compare by value', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002c2', 'Whenever the type has more than three fields', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002c2', 'Whenever the type will be serialised to JSON', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002c2', 'When the type needs inheritance', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002c3', 'Assignment copies the whole value, not a reference', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002c3', 'Boxing a struct allocates on the heap', 1, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002c3', 'A readonly struct documents and enforces immutability', 1, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002c3', 'A struct can inherit from another struct', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002c4', 'You can only read from IEnumerable; a List can also be written to', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002c4', 'List<T> is a class and only interfaces can be variant', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002c4', 'List<T> is not variant because it implements IEnumerable twice', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002c4', 'Covariance requires the type to be sealed', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002c5', 'Preserves the original stack trace instead of resetting it to this line', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002c5', 'Rethrows on the caller''s thread rather than this one', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002c5', 'Converts the exception to its base type', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002c5', 'Suppresses the finally block', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002c6', 'It filters without unwinding the stack, so a non-match keeps the context', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002c6', 'It retries the try block when the condition is false', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002c6', 'It is faster because the runtime can skip building the exception', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002c6', 'It catches exceptions thrown inside other catch blocks', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002c7', 'await returns the thread to the pool instead of blocking it', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002c7', 'Task.WhenAll on already-started tasks costs the slowest, not the sum', 1, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002c7', 'async void cannot be awaited, so its exceptions go unobserved', 1, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002c7', '.Result is a safe way to get a value from a Task in a web request', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002c8', 'Pass it onward and let OperationCanceledException propagate', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002c8', 'Poll IsCancellationRequested in a tight loop', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002c8', 'Call Dispose on it when the method returns', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002c8', 'Catch OperationCanceledException and return a default value', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002c9', 'Usually less than 400,000, because ++ is three operations that interleave', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002c9', 'Exactly 400,000: int writes are atomic in .NET', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002c9', 'An exception, because the runtime detects the race', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002c9', 'Exactly 400,000, but only on x86', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002ca', 'That it is a string with Length > 3, binding it to s where that holds', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002ca', 'That it is a string, then separately asserts the length', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002ca', 'That s already exists and equals a string of that length', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002ca', 'That the value is a string array of more than three elements', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002cb', 'True', 0, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002cb', 'False', 1, 2

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002cc', 'An event subscription that is never removed', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002cc', 'A static collection that is only ever added to', 1, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002cc', 'A cache with no eviction policy', 1, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002cc', 'A local variable going out of scope at the end of a method', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002cd', 'Releasing OS resources deterministically - the GC only frees memory', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002cd', 'Telling the GC to collect the object immediately', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002cd', 'Freeing the managed memory the object used', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002cd', 'Running a finaliser sooner than it otherwise would', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002ce', 'The JIT compiles and then re-optimises the hot path after the first rounds', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002ce', 'The GC has finished and stops interrupting', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002ce', 'Stopwatch becomes more accurate as the process ages', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002ce', 'The CPU cache fills so the loop stops touching memory', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002cf', 'In the domain project, so the database depends on the domain', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002cf', 'In the data-access project, next to its implementation', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002cf', 'In a shared Common project both reference', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002cf', 'In the web project, where the controller uses it', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002d0', 'The domain project references no framework and needs no host to test', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002d0', 'Dependencies are interfaces owned by the domain and passed to constructors', 1, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002d0', 'Types are internal by default, and public only where genuinely needed', 1, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002d0', 'Classes are named after the pattern used, so CourseServiceManagerImpl', 0, 4
  ) v;

CALL catalog_refresh_course_rollup('c0000001-0000-4000-8000-00000000000d');
CALL search_reindex_all();
